// agentlab plugin for OpenClaw (generated by `agentlab connect openclaw`).
// Records tool calls and blocks the ones your agentlab sandbox policy refuses.
// If agentlab cannot be started, calls are allowed (fail open) so your agent keeps working.
import { definePluginEntry } from "openclaw/plugin-sdk/plugin-entry";
import { spawnSync } from "node:child_process";

const HOOK = __HOOK_COMMAND__;
const PROJECT = __PROJECT__;

function run(payload) {
  const r = spawnSync(HOOK[0], HOOK.slice(1), {
    input: JSON.stringify({ client_type: "openclaw", cwd: PROJECT, ...payload }),
    encoding: "utf8",
    timeout: 10000,
  });
  return { code: r.status, message: (r.stderr || "").trim() };
}

const session = (ctx) => String(ctx?.sessionId ?? ctx?.sessionKey ?? ctx?.runId ?? "openclaw");

export default definePluginEntry({
  id: "agentlab",
  name: "agentlab",
  description: "Records agent activity and enforces the agentlab sandbox policy.",
  register(api) {
    api.on("before_tool_call", (event, ctx) => {
      const res = run({
        hook_event_name: "PreToolUse",
        session_id: session(ctx),
        tool_name: event.toolName,
        tool_input: event.params ?? {},
      });
      if (res.code === 2) return { block: true, blockReason: res.message || "Blocked by agentlab policy" };
    });
    api.on("agent_end", (event, ctx) => {
      run({ hook_event_name: "Stop", session_id: session(ctx) });
    });
  },
});
